_NOAH_SOURCE = '"""\nHYDROGEL_PACK — MM Plus Semi-Fixed Anchor v3 Reversion Boost\nIMC Prosperity 4 | Round 4\n\nBase:\n    Stable OBI-adjusted market making.\n\nMain overlay:\n    Semi-fixed fair-value anchor:\n        semi_anchor = 0.85 * 10000 + 0.15 * rolling_mean_500\n\nWhat v3 adds vs v2:\n    1. Deep cheap/rich passive ladders.\n    2. Small active entries only at extreme anchor deviations after reversal confirmation.\n    3. Active wrong-side inventory reduction when opposite anchor signal appears.\n\nImportant:\n    - No constant target chasing.\n    - No TMA/EMA quote filter.\n    - No Mark-flow dependency.\n    - Active crossing is rare and size-limited.\n"""\n\nfrom datamodel import OrderDepth, TradingState, Order\nfrom typing import List, Optional\nimport json\n\n\nPRODUCT = "HYDROGEL_PACK"\nPOS_LIMIT = 200\n\n# ─────────────────────────────────────────────────────────────\n# Base MM parameters\n# ─────────────────────────────────────────────────────────────\n\nOBI_ALPHA = 11.0\nHALF_SPREAD = 7\nPOSITION_SKEW_FACTOR = 0.10\nQUOTE_SIZE = 12\n\nOBI_SUPPRESS_THRESHOLD = 0.15\nEMERGENCY_THRESHOLD = 150\n\n# ─────────────────────────────────────────────────────────────\n# Semi-fixed anchor parameters\n# ─────────────────────────────────────────────────────────────\n\nFIXED_ANCHOR = 10000.0\nANCHOR_WINDOW = 500\nMIN_HISTORY_FOR_ANCHOR = 300\n\nFIXED_WEIGHT = 0.85\nROLLING_WEIGHT = 0.15\n\nANCHOR_EDGE = 18.0\nDEEP_ANCHOR_EDGE = 32.0\nEXTREME_ANCHOR_EDGE = 42.0\n\nMAX_ANCHOR_LONG = 85\nMAX_ANCHOR_SHORT = -65\n\nANCHOR_QTY = 6\nDEEP_ANCHOR_QTY = 10\n\n# Deep laddering\nENABLE_DEEP_LADDER = True\nLADDER_QTY_1 = 6\nLADDER_QTY_2 = 4\nLADDER_QTY_3 = 3\n\n# Momentum guards / reversal confirmation\nMOM_FAST = 5\nMOM_MED = 20\n\nFALLING_KNIFE_FAST = -10.0\nFALLING_KNIFE_MED = -22.0\n\nRISING_KNIFE_FAST = 10.0\nRISING_KNIFE_MED = 22.0\n\nSUPPRESS_OPPOSITE_ON_DEEP = True\nMIN_LONG_TO_KEEP_ASK_ON_DEEP_CHEAP = 45\nMAX_SHORT_TO_KEEP_BID_ON_DEEP_RICH = -45\n\n# ─────────────────────────────────────────────────────────────\n# Active reversion boost\n# ─────────────────────────────────────────────────────────────\n\nENABLE_ACTIVE_BOOST = True\n\nACTIVE_COOLDOWN_STEPS = 6\n\n# Fresh active entries are only allowed at extreme deviations.\nACTIVE_ENTRY_QTY = 5\nACTIVE_EXTREME_QTY = 8\n\nACTIVE_MAX_LONG = 105\nACTIVE_MAX_SHORT = -85\n\n# Wrong-side reduction is safer than opening fresh risk.\nACTIVE_REDUCE_QTY = 8\nACTIVE_STRONG_REDUCE_QTY = 12\n\nREDUCE_EDGE = 30.0\nSTRONG_REDUCE_EDGE = 42.0\n\nMAX_SPREAD_ACTIVE = 17\n\nVERBOSE = False\n\n\n# ─────────────────────────────────────────────────────────────\n# State / helpers\n# ─────────────────────────────────────────────────────────────\n\ndef load_state(trader_data: str) -> dict:\n    default = {\n        "mids": [],\n        "step": 0,\n        "last_active_step": -10_000,\n    }\n\n    if not trader_data:\n        return default\n\n    try:\n        data = json.loads(trader_data)\n        if not isinstance(data, dict):\n            return default\n\n        for k, v in default.items():\n            data.setdefault(k, v)\n\n        if not isinstance(data["mids"], list):\n            data["mids"] = []\n\n        return data\n\n    except Exception:\n        return default\n\n\ndef save_state(data: dict) -> str:\n    mids = data.get("mids", [])\n    if len(mids) > ANCHOR_WINDOW + 5:\n        data["mids"] = mids[-(ANCHOR_WINDOW + 5):]\n    return json.dumps(data)\n\n\ndef rolling_mean(values: List[float], window: int) -> Optional[float]:\n    if len(values) < window:\n        return None\n    vals = values[-window:]\n    return sum(vals) / len(vals)\n\n\ndef momentum(values: List[float], k: int) -> Optional[float]:\n    if len(values) <= k:\n        return None\n    return values[-1] - values[-1 - k]\n\n\ndef compute_semi_anchor(mids: List[float]) -> float:\n    roll = rolling_mean(mids, ANCHOR_WINDOW)\n    if roll is None:\n        return FIXED_ANCHOR\n    return FIXED_WEIGHT * FIXED_ANCHOR + ROLLING_WEIGHT * roll\n\n\ndef add_or_merge_order(orders: List[Order], product: str, price: int, qty: int):\n    if qty == 0:\n        return\n\n    for i, o in enumerate(orders):\n        if o.symbol == product and o.price == int(price):\n            if (o.quantity > 0 and qty > 0) or (o.quantity < 0 and qty < 0):\n                orders[i] = Order(product, int(price), int(o.quantity + qty))\n                return\n\n    orders.append(Order(product, int(price), int(qty)))\n\n\ndef used_buy_qty(orders: List[Order]) -> int:\n    return sum(o.quantity for o in orders if o.quantity > 0)\n\n\ndef used_sell_qty(orders: List[Order]) -> int:\n    return sum(-o.quantity for o in orders if o.quantity < 0)\n\n\ndef visible_best_ask_qty(sell_orders: dict, best_ask: int) -> int:\n    return max(0, abs(int(sell_orders.get(best_ask, 0))))\n\n\ndef visible_best_bid_qty(buy_orders: dict, best_bid: int) -> int:\n    return max(0, int(buy_orders.get(best_bid, 0)))\n\n\nclass Trader:\n\n    def run(self, state: TradingState):\n        result = {}\n        conversions = 0\n\n        data = load_state(state.traderData)\n        mids = [float(x) for x in data.get("mids", [])]\n        step = int(data.get("step", 0))\n\n        for product in state.order_depths:\n            if product != PRODUCT:\n                continue\n\n            order_depth: OrderDepth = state.order_depths[product]\n            orders: List[Order] = []\n\n            buy_orders = order_depth.buy_orders\n            sell_orders = order_depth.sell_orders\n\n            if not buy_orders or not sell_orders:\n                result[product] = orders\n                continue\n\n            best_bid = max(buy_orders.keys())\n            best_ask = min(sell_orders.keys())\n\n            bid_vol_1 = buy_orders[best_bid]\n            ask_vol_1 = abs(sell_orders[best_ask])\n\n            mid = (best_bid + best_ask) / 2.0\n            spread = best_ask - best_bid\n\n            mids.append(float(mid))\n            if len(mids) > ANCHOR_WINDOW + 5:\n                mids = mids[-(ANCHOR_WINDOW + 5):]\n\n            semi_anchor = compute_semi_anchor(mids)\n            mom5 = momentum(mids, MOM_FAST)\n            mom20 = momentum(mids, MOM_MED)\n\n            position = state.position.get(product, 0)\n\n            max_buy = POS_LIMIT - position\n            max_sell = POS_LIMIT + position\n\n            if max_buy <= 0 and max_sell <= 0:\n                result[product] = orders\n                continue\n\n            # ─────────────────────────────────────────────────────────────\n            # 1. Base OBI-adjusted market making\n            # ─────────────────────────────────────────────────────────────\n\n            total_vol_1 = bid_vol_1 + ask_vol_1\n            obi = (bid_vol_1 - ask_vol_1) / total_vol_1 if total_vol_1 > 0 else 0.0\n\n            fv = mid + OBI_ALPHA * obi\n\n            pos_skew = round(position * POSITION_SKEW_FACTOR)\n\n            our_bid_price = round(fv - HALF_SPREAD - pos_skew)\n            our_ask_price = round(fv + HALF_SPREAD - pos_skew)\n\n            our_bid_price = min(our_bid_price, best_ask - 1)\n            our_ask_price = max(our_ask_price, best_bid + 1)\n\n            bid_qty = min(QUOTE_SIZE, max_buy)\n            ask_qty = min(QUOTE_SIZE, max_sell)\n\n            suppress_bid = False\n            suppress_ask = False\n\n            if obi < -OBI_SUPPRESS_THRESHOLD:\n                # Downward OBI: avoid buying, sell tighter.\n                suppress_bid = True\n                our_ask_price = round(fv + 4 - pos_skew)\n                our_ask_price = max(our_ask_price, best_bid + 1)\n\n            elif obi > OBI_SUPPRESS_THRESHOLD:\n                # Upward OBI: avoid selling, buy tighter.\n                suppress_ask = True\n                our_bid_price = round(fv - 4 - pos_skew)\n                our_bid_price = min(our_bid_price, best_ask - 1)\n\n            # Emergency position reduction.\n            if position >= EMERGENCY_THRESHOLD:\n                suppress_bid = True\n                our_ask_price = max(round(fv - 5), best_bid + 1)\n                ask_qty = min(20, max_sell)\n\n            elif position <= -EMERGENCY_THRESHOLD:\n                suppress_ask = True\n                our_bid_price = min(round(fv + 5), best_ask - 1)\n                bid_qty = min(20, max_buy)\n\n            # ─────────────────────────────────────────────────────────────\n            # 2. Semi-fixed anchor state\n            # ─────────────────────────────────────────────────────────────\n\n            cheap_edge = semi_anchor - best_ask\n            rich_edge = best_bid - semi_anchor\n\n            falling_knife = False\n            rising_knife = False\n            rebound_confirmed = False\n            rollover_confirmed = False\n\n            if mom5 is not None and mom20 is not None:\n                falling_knife = (\n                    mom5 <= FALLING_KNIFE_FAST\n                    and mom20 <= FALLING_KNIFE_MED\n                )\n                rising_knife = (\n                    mom5 >= RISING_KNIFE_FAST\n                    and mom20 >= RISING_KNIFE_MED\n                )\n\n            if mom5 is not None:\n                rebound_confirmed = mom5 > 0\n                rollover_confirmed = mom5 < 0\n\n            enough_history = len(mids) >= MIN_HISTORY_FOR_ANCHOR\n\n            # ─────────────────────────────────────────────────────────────\n            # 3. Active reversion boost\n            # ─────────────────────────────────────────────────────────────\n\n            active_reason = "none"\n\n            if (\n                ENABLE_ACTIVE_BOOST\n                and enough_history\n                and spread <= MAX_SPREAD_ACTIVE\n                and step - int(data.get("last_active_step", -10_000)) >= ACTIVE_COOLDOWN_STEPS\n            ):\n                # A. Active wrong-side reduction:\n                # If long and price is rich + rolling over, sell some.\n                if (\n                    position > 35\n                    and rich_edge >= REDUCE_EDGE\n                    and rollover_confirmed\n                    and max_sell > 0\n                ):\n                    qty_cap = ACTIVE_STRONG_REDUCE_QTY if rich_edge >= STRONG_REDUCE_EDGE else ACTIVE_REDUCE_QTY\n                    qty = min(\n                        qty_cap,\n                        visible_best_bid_qty(buy_orders, best_bid),\n                        max_sell,\n                        position,  # reduction only, not opening fresh short in this branch\n                    )\n                    if qty > 0:\n                        add_or_merge_order(orders, product, int(best_bid), -int(qty))\n                        data["last_active_step"] = step\n                        active_reason = "reduce_long_rich_rollover"\n\n                # If short and price is cheap + rebounding, buy some.\n                elif (\n                    position < -25\n                    and cheap_edge >= REDUCE_EDGE\n                    and rebound_confirmed\n                    and max_buy > 0\n                ):\n                    qty_cap = ACTIVE_STRONG_REDUCE_QTY if cheap_edge >= STRONG_REDUCE_EDGE else ACTIVE_REDUCE_QTY\n                    qty = min(\n                        qty_cap,\n                        visible_best_ask_qty(sell_orders, best_ask),\n                        max_buy,\n                        -position,  # reduction only, not opening fresh long in this branch\n                    )\n                    if qty > 0:\n                        add_or_merge_order(orders, product, int(best_ask), int(qty))\n                        data["last_active_step"] = step\n                        active_reason = "cover_short_cheap_rebound"\n\n                # B. Small fresh active entries only at extreme deviations + confirmed reversal.\n                elif (\n                    cheap_edge >= EXTREME_ANCHOR_EDGE\n                    and rebound_confirmed\n                    and not falling_knife\n                    and position < ACTIVE_MAX_LONG\n                    and max_buy > 0\n                    and best_ask <= semi_anchor + 8\n                    and obi > -OBI_SUPPRESS_THRESHOLD\n                ):\n                    qty_cap = ACTIVE_EXTREME_QTY if cheap_edge >= EXTREME_ANCHOR_EDGE + 15 else ACTIVE_ENTRY_QTY\n                    qty = min(\n                        qty_cap,\n                        visible_best_ask_qty(sell_orders, best_ask),\n                        max_buy,\n                        ACTIVE_MAX_LONG - position,\n                    )\n                    if qty > 0:\n                        add_or_merge_order(orders, product, int(best_ask), int(qty))\n                        data["last_active_step"] = step\n                        active_reason = "active_buy_extreme_cheap_rebound"\n\n                elif (\n                    rich_edge >= EXTREME_ANCHOR_EDGE\n                    and rollover_confirmed\n                    and not rising_knife\n                    and position > ACTIVE_MAX_SHORT\n                    and max_sell > 0\n                    and best_bid >= semi_anchor - 12\n                    and obi < OBI_SUPPRESS_THRESHOLD\n                ):\n                    qty_cap = ACTIVE_EXTREME_QTY if rich_edge >= EXTREME_ANCHOR_EDGE + 15 else ACTIVE_ENTRY_QTY\n                    qty = min(\n                        qty_cap,\n                        visible_best_bid_qty(buy_orders, best_bid),\n                        max_sell,\n                        position - ACTIVE_MAX_SHORT,\n                    )\n                    if qty > 0:\n                        add_or_merge_order(orders, product, int(best_bid), -int(qty))\n                        data["last_active_step"] = step\n                        active_reason = "active_sell_extreme_rich_rollover"\n\n            # ─────────────────────────────────────────────────────────────\n            # 4. Semi-fixed passive overlay\n            # ─────────────────────────────────────────────────────────────\n\n            cheap_overlay = False\n            rich_overlay = False\n\n            cheap_qty = 0\n            rich_qty = 0\n\n            cheap_bid_prices = []\n            rich_ask_prices = []\n\n            # Cheap/passive long overlay\n            if (\n                enough_history\n                and cheap_edge >= ANCHOR_EDGE\n                and not falling_knife\n                and position < MAX_ANCHOR_LONG\n                and spread <= 17\n                and max_buy > used_buy_qty(orders)\n            ):\n                cheap_overlay = True\n                deep = cheap_edge >= DEEP_ANCHOR_EDGE\n\n                # Base top/bottom passive bid.\n                top_bid = min(best_bid + 1, best_ask - 1)\n\n                if deep and ENABLE_DEEP_LADDER:\n                    cheap_bid_prices = [top_bid, best_bid - 1, best_bid - 3]\n                    cheap_ladder_qtys = [LADDER_QTY_1, LADDER_QTY_2, LADDER_QTY_3]\n                else:\n                    cheap_bid_prices = [top_bid]\n                    cheap_ladder_qtys = [DEEP_ANCHOR_QTY if deep else ANCHOR_QTY]\n\n                # If base bid already top, do not duplicate top too aggressively.\n                if not suppress_bid and our_bid_price >= top_bid and not deep:\n                    cheap_bid_prices = [best_bid - 1]\n\n                if SUPPRESS_OPPOSITE_ON_DEEP and deep and position < MIN_LONG_TO_KEEP_ASK_ON_DEEP_CHEAP:\n                    suppress_ask = True\n\n            # Rich/passive short or long-exit overlay\n            if (\n                enough_history\n                and rich_edge >= ANCHOR_EDGE\n                and not rising_knife\n                and position > MAX_ANCHOR_SHORT\n                and spread <= 17\n                and max_sell > used_sell_qty(orders)\n            ):\n                rich_overlay = True\n                deep = rich_edge >= DEEP_ANCHOR_EDGE\n\n                top_ask = max(best_ask - 1, best_bid + 1)\n\n                if deep and ENABLE_DEEP_LADDER:\n                    rich_ask_prices = [top_ask, best_ask + 1, best_ask + 3]\n                    rich_ladder_qtys = [LADDER_QTY_1, LADDER_QTY_2, LADDER_QTY_3]\n                else:\n                    rich_ask_prices = [top_ask]\n                    rich_ladder_qtys = [DEEP_ANCHOR_QTY if deep else ANCHOR_QTY]\n\n                # If base ask already top, do not duplicate top too aggressively.\n                if not suppress_ask and our_ask_price <= top_ask and not deep:\n                    rich_ask_prices = [best_ask + 1]\n\n                if SUPPRESS_OPPOSITE_ON_DEEP and deep and position > MAX_SHORT_TO_KEEP_BID_ON_DEEP_RICH:\n                    suppress_bid = True\n\n            # ─────────────────────────────────────────────────────────────\n            # 5. Send base orders\n            # ─────────────────────────────────────────────────────────────\n\n            if not suppress_bid and bid_qty > 0 and our_bid_price < best_ask:\n                remaining = max_buy - used_buy_qty(orders)\n                qty = min(bid_qty, remaining)\n                if qty > 0:\n                    add_or_merge_order(orders, product, int(our_bid_price), int(qty))\n\n            if not suppress_ask and ask_qty > 0 and our_ask_price > best_bid:\n                remaining = max_sell - used_sell_qty(orders)\n                qty = min(ask_qty, remaining)\n                if qty > 0:\n                    add_or_merge_order(orders, product, int(our_ask_price), -int(qty))\n\n            # ─────────────────────────────────────────────────────────────\n            # 6. Send passive overlay ladders\n            # ─────────────────────────────────────────────────────────────\n\n            if cheap_overlay and cheap_bid_prices:\n                remaining_buy = max_buy - used_buy_qty(orders)\n                overlay_room = max(0, MAX_ANCHOR_LONG - position)\n\n                for px, q in zip(cheap_bid_prices, cheap_ladder_qtys):\n                    if remaining_buy <= 0 or overlay_room <= 0:\n                        break\n\n                    px = min(int(px), best_ask - 1)\n                    if px <= 0 or px >= best_ask:\n                        continue\n\n                    qty = min(int(q), remaining_buy, overlay_room)\n                    if qty > 0:\n                        add_or_merge_order(orders, product, px, qty)\n                        remaining_buy -= qty\n                        overlay_room -= qty\n\n            if rich_overlay and rich_ask_prices:\n                remaining_sell = max_sell - used_sell_qty(orders)\n                overlay_room = max(0, position - MAX_ANCHOR_SHORT)\n\n                for px, q in zip(rich_ask_prices, rich_ladder_qtys):\n                    if remaining_sell <= 0 or overlay_room <= 0:\n                        break\n\n                    px = max(int(px), best_bid + 1)\n                    if px <= best_bid:\n                        continue\n\n                    qty = min(int(q), remaining_sell, overlay_room)\n                    if qty > 0:\n                        add_or_merge_order(orders, product, px, -qty)\n                        remaining_sell -= qty\n                        overlay_room -= qty\n\n            if VERBOSE:\n                print(\n                    f"[SEMI_ANCHOR_V3] t={state.timestamp} step={step} pos={position} "\n                    f"mid={mid:.1f} anchor={semi_anchor:.2f} "\n                    f"cheap_edge={cheap_edge:.1f} rich_edge={rich_edge:.1f} "\n                    f"mom5={mom5 if mom5 is not None else \'NA\'} "\n                    f"mom20={mom20 if mom20 is not None else \'NA\'} "\n                    f"obi={obi:.2f} active={active_reason} "\n                    f"cheap={cheap_overlay} rich={rich_overlay} "\n                    f"orders={orders}"\n                )\n\n            result[product] = orders\n\n        data["mids"] = mids\n        data["step"] = step + 1\n\n        trader_data = save_state(data)\n        return result, conversions, trader_data'
_LUCAS_SOURCE = 'from __future__ import annotations\n\n"""\nStrat52: Redesigned HGP + strat46 voucher/VE engine.\n\nHGP:\n  - Pure passive MM at fixed FV=10000. Position cap +-80.\n  - OBI contrarian filter on quote sizing (neutral regime only).\n  - No Z-score, no floating anchor, no flip guards.\n\nVouchers/VE:\n  - Anchor formula retained (market prices at BS~TTE=8, not TTE_actual).\n  - VEV_6000/6500 sell code present; does not fill in backtest (bots trade at 0).\n  - Player overlay (Mark01, Mark22, Mark67, Mark55, Mark49) unchanged from strat46.\n"""\n\nimport json\nimport math\nfrom typing import Any, Dict, List, Tuple\n\ntry:\n    from datamodel import Order, OrderDepth, TradingState\nexcept ModuleNotFoundError:\n    from prosperity3bt.datamodel import Order, OrderDepth, TradingState\n\n\n# ---------------------------------------------------------------------------\n# Rolling implied volatility helpers\n# ---------------------------------------------------------------------------\n\n_T_MARKET = 8 / 365.0      # bots price at TTE=8 regardless of actual remaining TTE\n_SIGMA_REF = 0.22           # fallback / calibration sigma\n_IV_EMA_ALPHA = 0.005       # very slow EMA (~200-tick half-life)\n\n\ndef _norm_cdf(x: float) -> float:\n    return 0.5 * (1.0 + math.erf(x / math.sqrt(2.0)))\n\n\ndef _bs_call(S: float, K: float, T: float, sigma: float) -> float:\n    intrinsic = max(0.0, S - K)\n    if T <= 0 or sigma <= 0 or S <= 0:\n        return intrinsic\n    vs = sigma * math.sqrt(T)\n    d1 = (math.log(S / K) + 0.5 * sigma * sigma * T) / vs\n    return S * _norm_cdf(d1) - K * _norm_cdf(d1 - vs)\n\n\ndef _bs_invert_sigma(S: float, K: float, T: float, price: float) -> float:\n    """Binary search for implied vol from observed price. 40 iterations ~ 1e-12 accuracy."""\n    lo, hi = 0.05, 0.80\n    if price <= max(0.0, S - K):\n        return lo\n    for _ in range(40):\n        mid = (lo + hi) / 2.0\n        if _bs_call(S, K, T, mid) < price:\n            lo = mid\n        else:\n            hi = mid\n    return (lo + hi) / 2.0\n\n\n# ---------------------------------------------------------------------------\n# HGP constants\n# ---------------------------------------------------------------------------\n\nHGP = "HYDROGEL_PACK"\nHGP_FV = 10_000\nHGP_LIMIT = 200\nHGP_EDGE = 2            # passive quote offset from FV\nHGP_BASE_SIZE = 30      # units per passive quote (each side)\nHGP_CAP = 80            # hard position cap\nHGP_OBI_THRESH = 0.15   # contrarian OBI filter\n\n\n# ---------------------------------------------------------------------------\n# HGP helpers\n# ---------------------------------------------------------------------------\n\ndef _hgp_obi(depth: OrderDepth) -> float:\n    bid_vol = sum(max(0, int(v)) for v in depth.buy_orders.values())\n    ask_vol = sum(max(0, -int(v)) for v in depth.sell_orders.values())\n    total = bid_vol + ask_vol\n    if total <= 0:\n        return 0.0\n    return (bid_vol - ask_vol) / total\n\n\ndef _run_hgp(state: TradingState, cache: Dict[str, Any]) -> List[Order]:\n    depth = state.order_depths.get(HGP)\n    if depth is None or not depth.buy_orders or not depth.sell_orders:\n        return []\n\n    pos = int(state.position.get(HGP, 0))\n    bb = max(depth.buy_orders)\n    ba = min(depth.sell_orders)\n    obi = _hgp_obi(depth)\n\n    orders: List[Order] = []\n\n    # --- Passive MM: symmetric quotes at FV+-EDGE, inventory-skewed ---\n    inv_skew = int(round(pos / HGP_CAP * HGP_EDGE))\n    inv_skew = max(-HGP_EDGE, min(HGP_EDGE, inv_skew))\n\n    bid_px = min(HGP_FV - HGP_EDGE - inv_skew, ba - 1)\n    ask_px = max(HGP_FV + HGP_EDGE - inv_skew, bb + 1)\n    if bid_px >= ask_px or bid_px <= 0:\n        return orders\n\n    buy_cap  = max(0, HGP_CAP - pos)\n    sell_cap = max(0, HGP_CAP + pos)\n\n    buy_size  = HGP_BASE_SIZE\n    sell_size = HGP_BASE_SIZE\n\n    # Contrarian OBI: suppress the side the book is leaning toward\n    if obi > HGP_OBI_THRESH:\n        buy_size = max(0, buy_size // 3)\n    elif obi < -HGP_OBI_THRESH:\n        sell_size = max(0, sell_size // 3)\n\n    buy_size  = min(buy_size, buy_cap)\n    sell_size = min(sell_size, sell_cap)\n\n    if buy_size > 0:\n        orders.append(Order(HGP, int(bid_px), int(buy_size)))\n    if sell_size > 0:\n        orders.append(Order(HGP, int(ask_px), -int(sell_size)))\n\n    return orders\n\n\n# ---------------------------------------------------------------------------\n# Voucher engine — verbatim from strat46_round4_player_profile.py\n# (player-profile overlay kept for VE/vouchers; HGP overlay removed)\n# ---------------------------------------------------------------------------\n\nclass OrderManager:\n    def __init__(self, state: TradingState, limits: Dict[str, int], result: Dict[str, List[Order]]) -> None:\n        self.limits = limits\n        self.result = result\n        self.start_pos = {p: int(state.position.get(p, 0)) for p in limits}\n        self.expected_pos = dict(self.start_pos)\n        self.buy_sent = {p: 0 for p in limits}\n        self.sell_sent = {p: 0 for p in limits}\n\n    def add(self, product: str, price: int, qty: int) -> int:\n        if qty == 0 or product not in self.limits:\n            return 0\n        start = self.start_pos.get(product, 0)\n        limit = self.limits[product]\n        if qty > 0:\n            allowed = max(0, limit - start - self.buy_sent[product])\n            placed = min(int(qty), allowed)\n            if placed <= 0:\n                return 0\n            self.buy_sent[product] += placed\n        else:\n            allowed = max(0, limit + start - self.sell_sent[product])\n            placed = -min(int(-qty), allowed)\n            if placed >= 0:\n                return 0\n            self.sell_sent[product] += -placed\n        self.expected_pos[product] = self.expected_pos.get(product, start) + placed\n        self.result.setdefault(product, []).append(Order(product, int(price), int(placed)))\n        return abs(placed)\n\n    def pos(self, product: str) -> int:\n        return self.expected_pos.get(product, self.start_pos.get(product, 0))\n\n\nclass Trader:\n    VE = "VELVETFRUIT_EXTRACT"\n    VOUCHERS = [\n        "VEV_4000", "VEV_4500", "VEV_5000", "VEV_5100", "VEV_5200",\n        "VEV_5300", "VEV_5400", "VEV_5500", "VEV_6000", "VEV_6500",\n    ]\n    LIMITS = {VE: 200, **{v: 300 for v in VOUCHERS}}\n\n    ANCHOR = {\n        VE: 5262.0,\n        "VEV_4000": 1265.0, "VEV_4500": 764.0, "VEV_5000": 266.0,\n        "VEV_5100": 175.0,  "VEV_5200": 101.0, "VEV_5300": 50.0,\n        "VEV_5400": 16.0,   "VEV_5500": 6.0,\n        "VEV_6000": 0.5,    "VEV_6500": 0.5,\n    }\n    SOFT = {\n        VE: 200,\n        "VEV_4000": 24, "VEV_4500": 24,  "VEV_5000": 275,\n        "VEV_5100": 280, "VEV_5200": 285, "VEV_5300": 235,\n        "VEV_5400": 220, "VEV_5500": 12,\n        "VEV_6000": 0,  "VEV_6500": 0,\n    }\n    REG = {\n        "VEV_4000": (-3998.27, 1.000, 0.83), "VEV_4500": (-4497.00, 0.999, 0.76),\n        "VEV_5000": (-4550.49, 0.915, 1.40), "VEV_5100": (-3950.96, 0.784, 3.48),\n        "VEV_5200": (-2871.36, 0.565, 3.92), "VEV_5300": (-1704.69, 0.334, 3.41),\n        "VEV_5400": (-644.24,  0.126, 2.81), "VEV_5500": (-281.46,  0.055, 1.51),\n    }\n    STRIKE = {\n        "VEV_4000": 4000, "VEV_4500": 4500, "VEV_5000": 5000, "VEV_5100": 5100,\n        "VEV_5200": 5200, "VEV_5300": 5300, "VEV_5400": 5400, "VEV_5500": 5500,\n        "VEV_6000": 6000, "VEV_6500": 6500,\n    }\n    DELTA_APPROX = {\n        "VEV_4000": 1.00, "VEV_4500": 1.00, "VEV_5000": 0.93, "VEV_5100": 0.78,\n        "VEV_5200": 0.57, "VEV_5300": 0.33, "VEV_5400": 0.13, "VEV_5500": 0.05,\n        "VEV_6000": 0.00, "VEV_6500": 0.00,\n    }\n    CORE_BASKET = ("VEV_5000", "VEV_5100", "VEV_5200", "VEV_5300", "VEV_5400")\n\n    PLAYER_WINDOW = 7000\n    FLOW_MAX_ABS = 3.0\n    FLOW_FAIR_SCALE = {\n        VE: 1.8,\n        "VEV_4000": 3.0, "VEV_4500": 2.2, "VEV_5000": 1.4,\n        "VEV_5100": 1.1, "VEV_5200": 0.9, "VEV_5300": 0.7,\n        "VEV_5400": 0.45, "VEV_5500": 0.35,\n        "VEV_6000": 0.0, "VEV_6500": 0.0,\n    }\n    ACTIVE_PLAYER_PRODUCTS = (VE, "VEV_4000", "VEV_4500", "VEV_5000", "VEV_5100", "VEV_5200")\n\n    def bid(self) -> int:\n        return 1\n\n    def run(self, state: TradingState) -> Tuple[Dict[str, List[Order]], int, str]:\n        result: Dict[str, List[Order]] = {}\n        cache = self._load_cache(state.traderData)\n        timestamp = int(getattr(state, "timestamp", 0))\n        cache["now"] = timestamp\n\n        # --- HGP: passive MM ---\n        hgp_orders = _run_hgp(state, cache)\n        result[HGP] = hgp_orders\n\n        # --- Player signals for VE/vouchers ---\n        self._update_player_profile_signals(state, cache, timestamp)\n\n        # --- Vouchers + VE ---\n        for p in self.LIMITS:\n            result.setdefault(p, [])\n        om = OrderManager(state, self.LIMITS, result)\n        self._update_state(state, cache)\n\n        depth_ve = state.order_depths.get(self.VE)\n        if depth_ve is not None:\n            self._trade_ve_passive(depth_ve, cache, om)\n        for product in self.VOUCHERS:\n            depth = state.order_depths.get(product)\n            if depth is None:\n                continue\n            self._trade_voucher(product, depth, cache, om)\n        self._trade_player_overlay(state, cache, om, timestamp)\n        self._trade_noarb_lower_bound(state, cache, om)\n        self._delta_hedge_passive(state, cache, om)\n\n        cache["t"] = timestamp\n        return result, 0, json.dumps(cache, separators=(",", ":"))\n\n    # --- Player-profile overlay (VE/vouchers only) ---\n\n    def _update_player_profile_signals(self, state: TradingState, cache: Dict[str, Any], timestamp: int) -> None:\n        for book_name in ("own_trades", "market_trades"):\n            trade_book = getattr(state, book_name, {}) or {}\n            for product, trades in trade_book.items():\n                if product not in self.LIMITS:\n                    continue\n                for trade in trades:\n                    buyer = getattr(trade, "buyer", "") or ""\n                    seller = getattr(trade, "seller", "") or ""\n                    if not buyer or not seller:\n                        continue\n                    self._score_player_trade(cache, product, buyer, seller, timestamp)\n\n    def _score_player_trade(self, cache: Dict[str, Any], product: str, buyer: str, seller: str, timestamp: int) -> None:\n\n        if product in self.VOUCHERS or product == self.VE:\n            if buyer == "Mark 01":\n                self._register_flow(cache, product, +1.2, timestamp, "LEAN_WITH_MARK01_BUY")\n            if seller == "Mark 01":\n                self._register_flow(cache, product, -1.0, timestamp, "LEAN_WITH_MARK01_SELL")\n\n        if product in {"VEV_5200", "VEV_5300", "VEV_5400", "VEV_5500", "VEV_6000", "VEV_6500"}:\n            if seller == "Mark 22":\n                self._register_flow(cache, product, +1.0, timestamp, "MARK22_VOUCHER_SOURCE")\n            if buyer == "Mark 22":\n                self._register_flow(cache, product, -0.4, timestamp, "MARK22_RARE_BUY")\n\n        if product == self.VE:\n            if buyer == "Mark 67":\n                self._register_flow(cache, product, +1.4, timestamp, "MARK67_VE_BUY")\n            if seller == "Mark 67":\n                self._register_flow(cache, product, -0.7, timestamp, "MARK67_VE_SELL")\n            if buyer == "Mark 55":\n                self._register_flow(cache, product, -0.8, timestamp, "FADE_MARK55_BUY")\n            if seller == "Mark 55":\n                self._register_flow(cache, product, +0.8, timestamp, "FADE_MARK55_SELL")\n            if seller == "Mark 49":\n                self._register_flow(cache, product, +0.7, timestamp, "MARK49_VE_SOURCE")\n\n    def _register_flow(self, cache: Dict[str, Any], product: str, bias: float, timestamp: int, reason: str) -> None:\n        flows = cache.setdefault("flow", {})\n        current = flows.get(product, {})\n        old_bias = float(current.get("bias", 0.0)) if isinstance(current, dict) else 0.0\n        old_expires = int(current.get("expires", -1)) if isinstance(current, dict) else -1\n        if old_expires >= timestamp and old_bias * bias > 0:\n            bias = old_bias + bias * 0.35\n        bias = max(-self.FLOW_MAX_ABS, min(self.FLOW_MAX_ABS, bias))\n        flows[product] = {"bias": round(bias, 4), "expires": timestamp + self.PLAYER_WINDOW, "reason": reason}\n\n    def _flow_bias(self, cache: Dict[str, Any], product: str) -> float:\n        timestamp = int(cache.get("now", 0))\n        item = cache.get("flow", {}).get(product, {})\n        if not isinstance(item, dict) or int(item.get("expires", -1)) < timestamp:\n            return 0.0\n        return float(item.get("bias", 0.0))\n\n    def _flow_reason(self, cache: Dict[str, Any], product: str) -> str:\n        item = cache.get("flow", {}).get(product, {})\n        return str(item.get("reason", "")) if isinstance(item, dict) else ""\n\n    def _apply_flow_sizing(self, cache: Dict[str, Any], product: str, buy_size: int, sell_size: int) -> Tuple[int, int]:\n        bias = self._flow_bias(cache, product)\n        if bias >= 1.0:\n            buy_size = int(round(buy_size * (1.0 + min(0.75, 0.18 * bias))))\n            sell_size = int(round(sell_size * max(0.25, 1.0 - 0.22 * bias)))\n        elif bias <= -1.0:\n            sell_size = int(round(sell_size * (1.0 + min(0.75, 0.18 * abs(bias)))))\n            buy_size = int(round(buy_size * max(0.25, 1.0 - 0.22 * abs(bias))))\n        return max(0, buy_size), max(0, sell_size)\n\n    def _trade_player_overlay(self, state: TradingState, cache: Dict[str, Any], om: OrderManager, timestamp: int) -> None:\n        cooldown = cache.setdefault("player_overlay_cd", {})\n        for product in self.ACTIVE_PLAYER_PRODUCTS:\n            bias = self._flow_bias(cache, product)\n            if abs(bias) < 1.8 or int(cooldown.get(product, -1)) > timestamp:\n                continue\n            depth = state.order_depths.get(product)\n            bid, ask, _, _ = self._best_bid_ask(depth)\n            if bid is None or ask is None:\n                continue\n            pos = om.pos(product)\n            soft = min(self.SOFT.get(product, self.LIMITS[product]), 70 if product == self.VE else 65)\n            reason = self._flow_reason(cache, product)\n            qty = 2 if product in (self.VE, "VEV_4000", "VEV_4500") else 3\n            if "MARK22" in reason:\n                qty = 2\n            if bias > 0 and pos < soft:\n                om.add(product, ask, min(qty, soft - pos))\n                cooldown[product] = timestamp + 900\n            elif bias < 0 and pos > -soft:\n                om.add(product, bid, -min(qty, pos + soft))\n                cooldown[product] = timestamp + 900\n\n    # --- Voucher/VE engine ---\n\n    def _update_state(self, state: TradingState, cache: Dict[str, Any]) -> None:\n        ve_depth = state.order_depths.get(self.VE)\n        ve_mid = self._mid(ve_depth)\n        if ve_mid is None:\n            return\n        cache["ve_mid"] = round(float(ve_mid), 4)\n        self._ema(cache, "ve_slow", ve_mid, 0.025)\n        # Rolling implied vol from VEV_5400 (most liquid ATM, 286-413 trades/day)\n        ref_mid = self._mid(state.order_depths.get("VEV_5400"))\n        if ref_mid is not None and ref_mid > 0.5:\n            sigma_raw = _bs_invert_sigma(ve_mid, 5400, _T_MARKET, ref_mid)\n            self._ema(cache, "sigma_iv", sigma_raw, _IV_EMA_ALPHA)\n        vals = []\n        for product, (a, beta, std) in self.REG.items():\n            mid = self._mid(state.order_depths.get(product))\n            if mid is None:\n                continue\n            key = product.replace("_", "").lower()\n            resid = mid - (a + beta * ve_mid)\n            center = self._ema(cache, f"{key}_rv_center", resid, 0.018)\n            z = (resid - center) / max(std, 0.75)\n            cache[f"{key}_rv_z"] = round(z, 6)\n            if product in self.CORE_BASKET:\n                vals.append(z)\n        if vals:\n            vals.sort()\n            trimmed = vals[1:-1] if len(vals) >= 4 else vals\n            cache["rv_basket_z"] = round(sum(trimmed) / len(trimmed), 6)\n\n    def _trade_ve_passive(self, depth: OrderDepth, cache: Dict[str, Any], om: OrderManager) -> None:\n        bid, ask, bvol, avol = self._best_bid_ask(depth)\n        mid = self._mid(depth)\n        if bid is None or ask is None or mid is None:\n            return\n        spread = ask - bid\n        if spread <= 0:\n            return\n        ema = self._ema(cache, "ve_ema", mid, 0.045)\n        anchor = self.ANCHOR[self.VE]\n        fair = 0.6 * anchor + 0.4 * ema\n        fair += self.FLOW_FAIR_SCALE[self.VE] * self._flow_bias(cache, self.VE)\n        obi = self._obi(bvol, avol)\n        pos = om.pos(self.VE)\n        soft = self.SOFT[self.VE]\n        fair -= 0.030 * pos\n        edge = 0.7\n        buy_px = bid + 1 if spread >= 3 else bid\n        sell_px = ask - 1 if spread >= 3 else ask\n        base = 42\n        buy_size = base\n        sell_size = base\n        if obi > 0.15:\n            buy_size = max(0, buy_size // 3)\n        elif obi < -0.15:\n            sell_size = max(0, sell_size // 3)\n        if pos > soft * 0.55:\n            buy_size = 0\n            sell_size = int(sell_size * 1.4)\n        elif pos < -soft * 0.55:\n            sell_size = 0\n            buy_size = int(buy_size * 1.4)\n        buy_size, sell_size = self._apply_flow_sizing(cache, self.VE, buy_size, sell_size)\n        if buy_size > 0 and pos < soft and buy_px <= fair - edge:\n            om.add(self.VE, buy_px, min(buy_size, soft - pos))\n        if sell_size > 0 and pos > -soft and sell_px >= fair + edge:\n            om.add(self.VE, sell_px, -min(sell_size, pos + soft))\n\n    def _trade_voucher(self, product: str, depth: OrderDepth, cache: Dict[str, Any], om: OrderManager) -> None:\n        # Fix 3: VEV_6000/6500 re-enabled — sell at ask=1, BS fair ~0, free carry\n        if product in ("VEV_6000", "VEV_6500"):\n            best_bid = max(depth.buy_orders) if depth.buy_orders else None\n            sell_px = max(1, best_bid) if best_bid is not None else 1\n            sell_cap = self.LIMITS[product] + om.pos(product)\n            if sell_cap > 0:\n                om.add(product, sell_px, -min(30, sell_cap))\n            return\n        if product in ("VEV_4000", "VEV_4500"):\n            self._trade_mr(product, depth, cache, om, alpha=0.025, inv=0.080, edge=4.0, size=6, taker=False)\n            return\n        if product == "VEV_5000":\n            self._trade_mr(product, depth, cache, om, alpha=0.030, inv=0.080, edge=1.25, size=34, taker=True)\n        elif product in ("VEV_5100", "VEV_5200", "VEV_5300"):\n            self._trade_mr(product, depth, cache, om, alpha=0.035, inv=0.065, edge=0.65, size=44, taker=True)\n        elif product == "VEV_5400":\n            self._trade_mr(product, depth, cache, om, alpha=0.045, inv=0.035, edge=0.35, size=50, taker=True)\n        elif product == "VEV_5500":\n            self._trade_mr(product, depth, cache, om, alpha=0.050, inv=0.060, edge=1.2, size=8, taker=False)\n\n    def _trade_mr(self, product, depth, cache, om, alpha, inv, edge, size, taker):\n        bid, ask, bvol, avol = self._best_bid_ask(depth)\n        mid = self._mid(depth)\n        if bid is None or ask is None or mid is None:\n            return\n        spread = ask - bid\n        if spread <= 0:\n            return\n        key = product.replace("_", "").lower()\n        anchor = self.ANCHOR[product]\n        ema = self._ema(cache, f"{key}_ema", mid, alpha)\n        last = float(cache.get(f"{key}_last", mid))\n        abs_move = self._ema(cache, f"{key}_abs", abs(mid - last), 0.08)\n        cache[f"{key}_last"] = round(float(mid), 6)\n        micro = self._microprice(depth)\n        micro_edge = (micro - mid) if micro is not None else 0.0\n        anchor_fair = 0.72 * anchor + 0.28 * ema + 0.08 * micro_edge\n        # Scale fair by rolling IV ratio: prevents over-buying when market vol decays\n        sigma_iv = float(cache.get("sigma_iv", _SIGMA_REF))\n        fair = anchor_fair * (sigma_iv / _SIGMA_REF)\n        fair += self.FLOW_FAIR_SCALE.get(product, 0.0) * self._flow_bias(cache, product)\n        pos = om.pos(product)\n        soft = self.SOFT[product]\n        if soft <= 0:\n            return\n        fair -= inv * pos\n        dyn_edge = edge + min(1.5 * edge, 0.25 * abs_move)\n        if spread >= 3:\n            buy_px, sell_px = bid + 1, ask - 1\n        else:\n            buy_px, sell_px = bid, ask\n        richness = mid - fair\n        buy_size = sell_size = size\n        if richness > dyn_edge:\n            buy_size = max(1, size // 4)\n            sell_size = int(size * 1.6)\n        elif richness < -dyn_edge:\n            buy_size = int(size * 1.6)\n            sell_size = max(1, size // 4)\n        if pos > soft * 0.55:\n            buy_size = 0\n            sell_size = int(size * 2.0)\n        elif pos < -soft * 0.55:\n            buy_size = int(size * 2.0)\n            sell_size = 0\n        basket_z = float(cache.get("rv_basket_z", 0.0))\n        if product in self.CORE_BASKET:\n            if basket_z < -0.85:\n                buy_size = int(buy_size * 1.15)\n                sell_size = max(1, int(sell_size * 0.80)) if sell_size > 0 else 0\n            elif basket_z > 0.85:\n                sell_size = int(sell_size * 1.20)\n                buy_size = max(1, int(buy_size * 0.70)) if buy_size > 0 else 0\n        buy_size, sell_size = self._apply_flow_sizing(cache, product, buy_size, sell_size)\n        if product in ("VEV_5400", "VEV_5500") and pos <= 0:\n            sell_size = 0\n        if taker:\n            if pos > -soft and bid >= fair + dyn_edge + spread:\n                self._sweep_sell(product, depth, bid, min(sell_size, pos + soft), om)\n                pos = om.pos(product)\n            if pos < soft and ask <= fair - dyn_edge - spread:\n                self._sweep_buy(product, depth, ask, min(buy_size, soft - pos), om)\n                pos = om.pos(product)\n        if pos < soft and buy_size > 0 and buy_px <= fair - dyn_edge:\n            om.add(product, buy_px, min(buy_size, soft - pos))\n        if pos > -soft and sell_size > 0 and sell_px >= fair + dyn_edge:\n            om.add(product, sell_px, -min(sell_size, pos + soft))\n\n    def _trade_noarb_lower_bound(self, state, cache, om):\n        ve_depth = state.order_depths.get(self.VE)\n        ve_bid, _, _, _ = self._best_bid_ask(ve_depth)\n        if ve_bid is None:\n            return\n        for product, threshold, qty in (("VEV_4000", 1.0, 3), ("VEV_4500", 0.8, 3)):\n            depth = state.order_depths.get(product)\n            bid, ask, _, ask_vol = self._best_bid_ask(depth)\n            if bid is None or ask is None or ask_vol <= 0:\n                continue\n            lb = ve_bid - self.STRIKE[product]\n            edge = lb - ask\n            if edge < threshold:\n                continue\n            pos = om.pos(product)\n            soft = min(self.SOFT[product], 24)\n            if pos >= soft:\n                continue\n            buy_qty = min(qty, ask_vol, soft - pos)\n            filled = om.add(product, ask, buy_qty)\n            if filled > 0 and om.pos(self.VE) > -150:\n                om.add(self.VE, ve_bid, -min(filled, 150 + om.pos(self.VE)))\n\n    def _delta_hedge_passive(self, state, cache, om):\n        ve_depth = state.order_depths.get(self.VE)\n        ve_bid, ve_ask, _, _ = self._best_bid_ask(ve_depth)\n        if ve_bid is None or ve_ask is None:\n            return\n        net_delta = 0.0\n        for v in self.VOUCHERS:\n            net_delta += om.pos(v) * self.DELTA_APPROX.get(v, 0.0)\n        ve_pos = om.pos(self.VE)\n        target_ve = -net_delta * 0.5\n        gap = target_ve - ve_pos\n        if abs(gap) < 12:\n            return\n        soft = 150\n        if gap > 0:\n            qty = min(int(gap), max(0, soft - ve_pos), 6)\n            if qty > 0:\n                om.add(self.VE, int(ve_bid), qty)\n        else:\n            qty = min(int(-gap), max(0, ve_pos + soft), 6)\n            if qty > 0:\n                om.add(self.VE, int(ve_ask), -qty)\n\n    def _sweep_buy(self, product, depth, max_price, qty, om):\n        rem = max(0, int(qty))\n        for price, vol in sorted(depth.sell_orders.items()):\n            if rem <= 0 or price > max_price:\n                break\n            rem -= om.add(product, int(price), min(rem, -int(vol)))\n\n    def _sweep_sell(self, product, depth, min_price, qty, om):\n        rem = max(0, int(qty))\n        for price, vol in sorted(depth.buy_orders.items(), reverse=True):\n            if rem <= 0 or price < min_price:\n                break\n            rem -= om.add(product, int(price), -min(rem, int(vol)))\n\n    def _best_bid_ask(self, depth):\n        if depth is None:\n            return None, None, 0, 0\n        bid = max(depth.buy_orders) if depth.buy_orders else None\n        ask = min(depth.sell_orders) if depth.sell_orders else None\n        bvol = int(depth.buy_orders[bid]) if bid is not None else 0\n        avol = -int(depth.sell_orders[ask]) if ask is not None else 0\n        return bid, ask, bvol, avol\n\n    def _mid(self, depth):\n        bid, ask, _, _ = self._best_bid_ask(depth)\n        if bid is None or ask is None:\n            return None\n        return (bid + ask) / 2.0\n\n    def _microprice(self, depth):\n        bid, ask, bvol, avol = self._best_bid_ask(depth)\n        if bid is None or ask is None:\n            return None\n        total = bvol + avol\n        if total <= 0:\n            return (bid + ask) / 2.0\n        return (ask * bvol + bid * avol) / total\n\n    def _obi(self, bvol, avol):\n        total = bvol + avol\n        if total <= 0:\n            return 0.0\n        return (bvol - avol) / total\n\n    def _ema(self, cache, key, value, alpha):\n        old = cache.get(key)\n        new = (1 - alpha) * float(old) + alpha * value if isinstance(old, (int, float)) else value\n        cache[key] = round(float(new), 6)\n        return float(new)\n\n    def _load_cache(self, trader_data):\n        if not trader_data:\n            return {}\n        try:\n            parsed = json.loads(trader_data)\n            return parsed if isinstance(parsed, dict) else {}\n        except (TypeError, json.JSONDecodeError):\n            return {}'


def _load_embedded_trader(source: str, name: str):
    module = types.ModuleType(name)
    module.__dict__["__name__"] = name
    old_datamodel = sys.modules.get("datamodel")
    sys.modules["datamodel"] = _datamodel
    try:
        exec(source, module.__dict__)
        return module.Trader()
    finally:
        if old_datamodel is None:
            sys.modules.pop("datamodel", None)
        else:
            sys.modules["datamodel"] = old_datamodel


HGP = "HYDROGEL_PACK"
NON_HGP_PRODUCTS = {
    "VELVETFRUIT_EXTRACT",
    "VEV_4000",
    "VEV_4500",
    "VEV_5000",
    "VEV_5100",
    "VEV_5200",
    "VEV_5300",
    "VEV_5400",
    "VEV_5500",
    "VEV_6000",
    "VEV_6500",
}


def _load_state(raw: str) -> dict[str, Any]:
    if not raw:
        return {"hgp": "", "core": ""}
    try:
        data = json.loads(raw)
    except Exception:
        return {"hgp": "", "core": ""}
    if not isinstance(data, dict):
        return {"hgp": "", "core": ""}
    return {"hgp": data.get("hgp", ""), "core": data.get("core", "")}


def _sub_state(state: TradingState, products: set[str], trader_data: str) -> TradingState:
    return TradingState(
        traderData=trader_data,
        timestamp=state.timestamp,
        listings={p: v for p, v in state.listings.items() if p in products},
        order_depths={p: v for p, v in state.order_depths.items() if p in products},
        own_trades={p: v for p, v in state.own_trades.items() if p in products},
        market_trades={p: v for p, v in state.market_trades.items() if p in products},
        position={p: v for p, v in state.position.items() if p in products},
        observations=state.observations,
    )


class Trader:
    def __init__(self):
        self.hgp_trader = _load_embedded_trader(_NOAH_SOURCE, "embedded_noah_hydrogel_525513")
        self.core_trader = _load_embedded_trader(_LUCAS_SOURCE, "embedded_lucasv1_517405")

    def run(self, state: TradingState):
        data = _load_state(state.traderData)
        result: Dict[str, List[Order]] = {}

        hgp_orders, _, hgp_data = self.hgp_trader.run(_sub_state(state, {HGP}, data["hgp"]))
        for product, orders in hgp_orders.items():
            if product == HGP:
                result[product] = orders

        core_orders, _, core_data = self.core_trader.run(_sub_state(state, NON_HGP_PRODUCTS, data["core"]))
        for product, orders in core_orders.items():
            if product in NON_HGP_PRODUCTS:
                result[product] = orders

        trader_data = json.dumps({"hgp": hgp_data, "core": core_data}, separators=(",", ":"))
        return result, 0, trader_data